class Solution {
public:
    int minimumAverageDifference(vector<int>& nums) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;

        long long prefix = 0;
        long long minDiff = 1e18;
        int result = 0;

        for (int i = 0; i < n; i++) {
            prefix += nums[i];
            long long leftAvg = prefix / (i + 1);
            long long rightSum = total - prefix;
            int rightCount = n - i - 1;
            long long rightAvg = (rightCount == 0) ? 0 : rightSum / rightCount;
            long long diff = leftAvg - rightAvg;
            if (diff < 0) diff = -diff;
            if (diff < minDiff) {
                minDiff = diff;
                result = i;
            }
        }
        return result;
    }
};
